// src/components/Dashboard.jsx
// ... (imports stay the same)

const Dashboard = () => {
  // ... (states stay the same)

  useEffect(() => {
    if (!apiService.isAuthenticated()) {
      navigate('/login');
      return;
    }
    loadTasks();
  }, [navigate]);

  useEffect(() => {
    filterTasks();
  }, [tasks, currentFilter]);

  const loadTasks = async () => {
    setLoading(true);
    try {
      const result = await apiService.getTasks();
      if (result.success) {
        setTasks(result.data.data || []);
      } else {
        console.error('Failed to load tasks:', result.error);
        if (result.error && result.error.includes('token')) {
          handleLogout();
        }
      }
    } catch (error) {
      console.error('Error loading tasks:', error);
    } finally {
      setLoading(false);
    }
  };

  const filterTasks = () => {
    let filtered = [...tasks];
    switch (currentFilter) {
      case 'today':
        const today = new Date().toDateString();
        filtered = tasks.filter(task => {
          const taskDate = new Date(task.date_time).toDateString(); // ✅ use Django field
          return taskDate === today;
        });
        break;
      case 'pending':
        filtered = tasks.filter(task => !task.is_complete);
        break;
      case 'completed':
        filtered = tasks.filter(task => task.is_complete);
        break;
      case 'advance':
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        filtered = tasks.filter(task => {
          if (task.date_time) {
            const taskDate = new Date(task.date_time);
            return taskDate >= tomorrow;
          }
          return false;
        });
        break;
      default:
        filtered = tasks;
    }
    setFilteredTasks(filtered);
  };

  // ... (functions unchanged: handleAddTask, handleEditTask, etc.)

  const formatDate = (dateString) => {
    if (!dateString) return 'No due date';
    return new Date(dateString).toLocaleDateString();
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard" data-theme={theme}>
      {/* Navbar & Sidebar unchanged */}

      {/* Main Content */}
      <main className={`main-content ${sidebarOpen ? 'shifted' : ''}`}>
        <div className="content-header">
          <h1 className="page-title">Tasks</h1>
          <button className="add-User_Task-btn" onClick={handleAddTask}>
            + Add User_Task
          </button>
        </div>

        {/* Filters unchanged */}

        {/* Task List */}
        <div className="User_Task-list">
          {filteredTasks.length === 0 ? (
            <div className="no-tasks">
              <p>No tasks found for the selected filter.</p>
              <button className="add-User_Task-btn" onClick={handleAddTask}>
                Create your first User_Task
              </button>
            </div>
          ) : (
            filteredTasks.map((task, index) => (
              <div key={task.id} className="User_Task-card" style={{animationDelay: `${index * 0.1}s`}}>
                <div className="User_Task-header">
                  <div>
                    <div className={`User_Task-title ${task.is_complete ? 'completed' : ''}`}>
                      {task.User_Task}
                    </div>
                    <div className="User_Task-meta">
                      {/* ✅ Corrected to match Django field */}
                      <span>Due: {formatDate(task.date_time)}</span>
                      {/* ✅ Show Django status field */}
                      <span>Status: {task.status}</span>
                      <span>{task.is_complete ? 'Completed' : 'Pending'}</span>
                    </div>
                  </div>
                  <div className="User_Task-actions">
                    <button
                      className={`action-btn ${task.is_complete ? 'complete-btn' : 'complete-btn'}`}
                      onClick={() => handleCompleteTask(task)}
                    >
                      {task.is_complete ? 'Undo' : 'Complete'}
                    </button>
                    <button
                      className="action-btn edit-btn"
                      onClick={() => handleEditTask(task)}
                    >
                      Edit
                    </button>
                    <button
                      className="action-btn delete-btn"
                      onClick={() => handleDeleteTask(task.id)}
                    >
                      Delete
                    </button>
                  </div>
                </div>
                {task.descri && (
                  <div className="User_Task-description">
                    {task.descri}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </main>

      {/* Modal */}
      {showTaskModal && (
        <TaskModal
          User_Task={editingTask}
          onSave={handleTaskSaved}
          onClose={() => setShowTaskModal(false)}
          statusOptions={['Today', 'Tomorrow', 'Advance']} // ✅ pass choices
        />
      )}
    </div>
  );
};

export default Dashboard;
